structs.bitset_t:
typedef struct bitset_t
{
    _Bool flip;
    size_t size;
    size_t count;
    uint8_t *array;
} bitset_t;

functions.cb_bitset_new:
bitset_t *cb_bitset_new(size_t nb_bits)
{
    bitset_t *bs = (bitset_t *)calloc(1, sizeof(bitset_t));
    bs->array = (uint8_t *)calloc(((nb_bits + 7) >> 3), sizeof(uint8_t));
    bs->size = nb_bits;
    return bs;
}

functions.cb_bitset_set:
void cb_bitset_set(bitset_t *bs, size_t idx, _Bool value)
{
    _Bool flip_value = bs->flip ? !value : value;
    size_t previous_count = __builtin_popcount(bs->array[((idx) >> 3)]);
    if (flip_value)
    {
        bs->array[((idx) >> 3)] |= (1 << ((idx) & 0x7));
    }
    else
    {
        bs->array[((idx) >> 3)] &= ~(1 << ((idx) & 0x7));
    }
    bs->count += (__builtin_popcount(bs->array[((idx) >> 3)]) - previous_count);
}

functions.cb_bitset_to_string:
char *cb_bitset_to_string(bitset_t *bs)
{
    char *res = (char *)malloc(sizeof(char) * (bs->size + 1));
    for (size_t i = 0; i < bs->size; i++)
    {
        res[i] = cb_bitset_test(bs, i) ? '1' : '0';
    }
    res[bs->size] = '\0';
    return res;
}

functions.cb_bitset_write:
void cb_bitset_write(bitset_t *bs, const char *path)
{
    FILE *file = fopen(path, "wb");
    size_t bytes_to_write = ((bs->size + 7) >> 3);
    size_t bytes_writen = 0;
    size_t total_writen = 0;
    if (file == ((void *)0))
    {
        fprintf(stdout, "%s\n", strerror((*__errno_location())));
        exit(1);
    }
    fwrite(&(bs->size), sizeof(size_t), 1, file);
    fwrite(&(bs->count), sizeof(size_t), 1, file);
    fwrite(&(bs->flip), sizeof(_Bool), 1, file);
    while ((bytes_writen = fwrite(bs->array + total_writen, sizeof(uint8_t), bytes_to_write - total_writen, file)) > 0)
    {
        total_writen += bytes_writen;
    }
    fclose(file);
}

functions.cb_bitset_read:
bitset_t *cb_bitset_read(const char *path)
{
    FILE *file = fopen(path, "rb");
    size_t size = 0;
    if (file == ((void *)0))
    {
        fprintf(stdout, "%s\n", strerror((*__errno_location())));
        exit(1);
    }
    fread(&size, sizeof(size_t), 1, file);
    bitset_t *bs = cb_bitset_new(size);
    fread(&(bs->count), sizeof(size_t), 1, file);
    fread(&(bs->flip), sizeof(_Bool), 1, file);
    while (fread(bs->array, sizeof(uint8_t), bs->size, file) > 0)
        ;
    fclose(file);
    return bs;
}
